mkdir -p /usr/share/nginx/html; printf '%s\n' '<!doctype html>' '<html><head><title>Nginx on node1</title></head><body><h1>Nginx is running on node1</h1><p>TCP port 6700</p></body></html>' > /usr/share/nginx/html/index.html; chmod 0644 /usr/share/nginx/html/index.html; cat > /etc/nginx/conf.d/port-6700.conf <<'ANTRIEB_NGINX_EOF'
server {
    listen 6700 default_server;
    listen [::]:6700 default_server;
    server_name _;
    root /usr/share/nginx/html;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
ANTRIEB_NGINX_EOF
nginx -t

